graphql.query:
query PanelRecepcion($fecha: Date) {
  panelRecepcion(fecha: $fecha) {
    fecha
    negocio { nombre zonaHoraria }
    citasDelDia { horaLocal clienteNombre clienteCelular servicio { nombre } estado }
    metricasDelMes { desde hasta totalCitas atendidas noAsistio canceladas ocupacion tasaInasistencia }
  }
}

query {
  negocio {
    nombre slugPublico zonaHoraria
    servicios { id nombre duracionMin precio activo }
    profesionales { id nombre servicios { nombre } horarios { diaSemana horaInicio horaFin } }
  }
}

query Agenda($p: ID!, $f: Date!) {
  agenda(profesionalId: $p, fecha: $f) { id horaLocal clienteNombre clienteCelular estado servicio { nombre } }
}

query Metricas($d: Date!, $h: Date!) {
  metricas(desde: $d, hasta: $h) {
    totalCitas atendidas noAsistio canceladas ocupacion tasaInasistencia
    topServicios { cantidad servicio { nombre } }
  }
}

mutation Crear($e: ServicioInput!) {
  crearServicio(entrada: $e) { id nombre duracionMin precio activo }
}

mutation Actualizar($id: ID!, $e: ServicioInput!) {
  actualizarServicio(id: $id, entrada: $e) { id nombre precio }
}

mutation Crear($e: ProfesionalInput!) {
  crearProfesional(entrada: $e) { id nombre activo servicios { nombre } }
}

mutation Horario($p: ID!, $h: [HorarioInput!]!) {
  definirHorario(profesionalId: $p, horarios: $h) { nombre horarios { diaSemana horaInicio horaFin } }
}

mutation Bloquear($e: BloqueoInput!) {
  crearBloqueo(entrada: $e) { id inicio fin motivo }
}

query Bloqueos($p: ID!) {
  bloqueos(profesionalId: $p) { id inicio fin motivo }
}

mutation Cancelar($c: ID!) {
  cancelarCita(citaId: $c, motivo: "El profesional se incapacitó") { id estado horaLocal }
}

mutation Asistencia($c: ID!) {
  registrarAsistencia(citaId: $c, estado: CANCELADA) { id }
}
